// このロジックは src/normalize.js と同一内容を手動で複製している（n8n Codeノードは
// 外部モジュールをimportできないため）。変更時は両方を同期させること。

const TRACKING_PARAMS = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'fbclid', 'gclid', 'ref'];

// http(s) URLのみを対象とする単純なパーサー。
// 注意：n8nのCodeノードのサンドボックス（JS Task Runner）にはグローバルの`URL`/
// `URLSearchParams`が存在せず、`require('url')`も許可されていないため、標準の
// `URL`クラスを一切使わずに正規表現と文字列操作のみで実装している。
const ABSOLUTE_HTTP_URL_PATTERN = /^(https?):\/\/([^/?#:]+)(?::(\d+))?([^?#]*)(?:\?([^#]*))?(?:#.*)?$/i;

function parseHttpUrl(rawUrl) {
  if (!rawUrl || typeof rawUrl !== 'string') return null;
  const match = ABSOLUTE_HTTP_URL_PATTERN.exec(rawUrl.trim());
  if (!match) return null;
  const [, protocol, hostname, port, path, query] = match;
  return { protocol: protocol.toLowerCase(), hostname, port: port || '', pathname: path || '', query: query || '' };
}

function decodeQueryKey(rawKey) {
  try {
    return decodeURIComponent(rawKey.replace(/\+/g, ' '));
  } catch (e) {
    return rawKey;
  }
}

function normalizeUrl(rawUrl) {
  const parsed = parseHttpUrl(rawUrl);
  if (!parsed) return null;

  const hostname = parsed.hostname.toLowerCase();
  const port = (parsed.protocol === 'http' && parsed.port === '80') || (parsed.protocol === 'https' && parsed.port === '443')
    ? ''
    : parsed.port;

  let pathname = parsed.pathname || '/';
  if (!pathname.startsWith('/')) pathname = `/${pathname}`;
  if (pathname.length > 1 && pathname.endsWith('/')) pathname = pathname.slice(0, -1);

  const params = [];
  for (const pair of parsed.query ? parsed.query.split('&') : []) {
    if (!pair) continue;
    const eqIdx = pair.indexOf('=');
    const rawKey = eqIdx === -1 ? pair : pair.slice(0, eqIdx);
    const rawValue = eqIdx === -1 ? '' : pair.slice(eqIdx + 1);
    if (TRACKING_PARAMS.includes(decodeQueryKey(rawKey))) continue;
    params.push([rawKey, rawValue]);
  }
  params.sort((a, b) => {
    const ka = decodeQueryKey(a[0]);
    const kb = decodeQueryKey(b[0]);
    return ka < kb ? -1 : ka > kb ? 1 : 0;
  });
  const query = params.map(([k, v]) => (v ? `${k}=${v}` : k)).join('&');

  return `${parsed.protocol}://${hostname}${port ? `:${port}` : ''}${pathname}${query ? `?${query}` : ''}`;
}

function getHostname(rawUrl) {
  const parsed = parseHttpUrl(rawUrl);
  return parsed ? parsed.hostname.toLowerCase() : null;
}

function classifySourceType(url, officialUrl) {
  const h1 = getHostname(url);
  const h2 = getHostname(officialUrl);
  if (!h1 || !h2) return 'external';
  return h1 === h2 ? 'official' : 'external';
}

function dedupeSources(rawSources) {
  const map = new Map();
  const order = [];
  let counter = 0;
  for (const s of rawSources) {
    const normalized = normalizeUrl(s.url);
    if (!normalized) continue;
    if (!map.has(normalized)) {
      counter += 1;
      map.set(normalized, {
        id: 'src' + counter,
        url: s.url,
        normalized_url: normalized,
        title: s.title || null,
        snippet: s.snippet || null,
        source_type: s.source_type,
        origin: [s.origin],
      });
      order.push(normalized);
    } else {
      const entry = map.get(normalized);
      if (!entry.title && s.title) entry.title = s.title;
      if (!entry.snippet && s.snippet) entry.snippet = s.snippet;
      if (!entry.origin.includes(s.origin)) entry.origin.push(s.origin);
    }
  }
  return order.map((k) => map.get(k));
}

function extractErrorMessage(err) {
  if (typeof err === 'string') return err;
  if (err && typeof err === 'object') return err.message || JSON.stringify(err);
  return 'unknown error';
}

function buildSearchSummary(searchItem, query, maxResults) {
  if (searchItem && searchItem.error) {
    return { status: 'error', query, max_results: maxResults, returned_count: 0, error_message: extractErrorMessage(searchItem.error) };
  }
  const results = Array.isArray(searchItem && searchItem.results) ? searchItem.results : [];
  if (results.length === 0) {
    return { status: 'empty', query, max_results: maxResults, returned_count: 0 };
  }
  return { status: 'ok', query, max_results: maxResults, returned_count: results.length };
}

function buildExtractSummary(extractItem, requestedUrl) {
  if (extractItem && extractItem.error) {
    return { status: 'error', requested_url: requestedUrl, error_message: extractErrorMessage(extractItem.error), failed_urls: [] };
  }
  const failed = Array.isArray(extractItem && extractItem.failed_results) ? extractItem.failed_results : [];
  if (failed.length > 0) {
    return {
      status: 'error',
      requested_url: requestedUrl,
      error_message: failed.map((f) => f.url + ': ' + f.error).join('; '),
      failed_urls: failed.map((f) => f.url),
    };
  }
  const results = Array.isArray(extractItem && extractItem.results) ? extractItem.results : [];
  if (results.length === 0) {
    return { status: 'empty', requested_url: requestedUrl, failed_urls: [] };
  }
  return { status: 'ok', requested_url: requestedUrl, failed_urls: [] };
}

function buildResearchOutput({ input, searchItem, extractItem }) {
  const query = input.company_name + ' 会社概要';
  const maxResults = 3;
  const search = buildSearchSummary(searchItem, query, maxResults);
  const extract = buildExtractSummary(extractItem, input.official_url);

  const rawSources = [];

  if (extract.status === 'ok') {
    for (const r of extractItem.results) {
      rawSources.push({
        url: r.url,
        title: null,
        snippet: r.raw_content ? String(r.raw_content).slice(0, 500) : null,
        source_type: classifySourceType(r.url, input.official_url),
        origin: 'extract',
      });
    }
  }

  if (search.status === 'ok') {
    for (const r of searchItem.results) {
      rawSources.push({
        url: r.url,
        title: r.title || null,
        snippet: r.content || null,
        source_type: classifySourceType(r.url, input.official_url),
        origin: 'search',
      });
    }
  }

  const sources = dedupeSources(rawSources);

  const warnings = [];
  if (search.status === 'error') warnings.push('Tavily Search呼び出しに失敗しました: ' + search.error_message);
  if (search.status === 'empty') warnings.push('Tavily Searchの結果が0件でした。');
  if (extract.status === 'error') warnings.push('Tavily Extractに失敗しました: ' + extract.error_message);
  if (sources.length === 0) warnings.push('有効な出典が1件も取得できませんでした。');

  return {
    input,
    search,
    extract,
    sources,
    warnings,
    generated_at: new Date().toISOString(),
  };
}

const input = $('Input Ready').first().json;
const searchItem = $('Tavily Search').first().json;
const extractItem = $('Tavily Extract').first().json;

return [{ json: buildResearchOutput({ input, searchItem, extractItem }) }];

// このロジックは src/sanitize_input.js と同一内容を手動で複製している（n8n Codeノードは
// 外部モジュールをimportできないため）。変更時は両方を同期させること。
// n8n Codeノードのサンドボックスには`URL`が存在しないため、正規表現＋文字列操作のみで実装する。

const MAX_COMPANY_NAME_LENGTH = 200;
const MAX_RESEARCH_PURPOSE_LENGTH = 500;

const ABSOLUTE_HTTP_URL_PATTERN = /^(https?):\/\/(\[[0-9a-fA-F:]+\]|[^/?#:]+)(?::(\d+))?([^?#]*)(?:\?([^#]*))?(?:#.*)?$/i;

function parseHttpUrl(rawUrl) {
  if (!rawUrl || typeof rawUrl !== 'string') return null;
  const match = ABSOLUTE_HTTP_URL_PATTERN.exec(rawUrl.trim());
  if (!match) return null;
  const [, protocol, hostname] = match;
  return { protocol: protocol.toLowerCase(), hostname: hostname.toLowerCase() };
}

const BLOCKED_HOSTNAME_PATTERNS = [
  /^localhost$/,
  /^127\./,
  /^10\./,
  /^192\.168\./,
  /^172\.(1[6-9]|2\d|3[01])\./,
  /^169\.254\./,
  /^0\.0\.0\.0$/,
  /^\[::1\]$/,
  /^\[fe80:/,
  /^\[fc00:/,
  /^\[fd00:/,
];

function isBlockedHostname(hostname) {
  if (!hostname) return true;
  return BLOCKED_HOSTNAME_PATTERNS.some((pattern) => pattern.test(hostname));
}

function sanitizeText(raw, maxLength) {
  if (typeof raw !== 'string') return '';
  return raw.trim().slice(0, maxLength);
}

function sanitizeOfficialUrl(raw) {
  if (typeof raw !== 'string' || raw.trim() === '') {
    return { valid: false, url: '', reason: '公式URLが入力されていません' };
  }
  const trimmed = raw.trim().slice(0, 500);
  const parsed = parseHttpUrl(trimmed);
  if (!parsed) {
    return { valid: false, url: '', reason: '公式URLはhttp(s)から始まる形式で入力してください' };
  }
  if (isBlockedHostname(parsed.hostname)) {
    return { valid: false, url: '', reason: '公式URLに内部向け・ループバックアドレスは指定できません' };
  }
  return { valid: true, url: trimmed, reason: null };
}

function sanitizeResearchInput(raw) {
  const company_name = sanitizeText(raw?.company_name, MAX_COMPANY_NAME_LENGTH);
  const research_purpose = sanitizeText(raw?.research_purpose, MAX_RESEARCH_PURPOSE_LENGTH);
  const urlResult = sanitizeOfficialUrl(raw?.official_url);

  const errors = [];
  if (!company_name) errors.push('会社名が入力されていません');
  if (!urlResult.valid) errors.push(urlResult.reason);

  return {
    valid: errors.length === 0,
    error_message: errors.length > 0 ? errors.join(' / ') : null,
    input: {
      company_name,
      official_url: urlResult.url,
      research_purpose,
    },
  };
}

const body = $json.body || {};
const result = sanitizeResearchInput(body);

return [{
  json: {
    company_name: result.input.company_name,
    official_url: result.input.official_url,
    research_purpose: result.input.research_purpose,
    _source: 'webhook',
    _input_error: result.valid ? '' : result.error_message,
  },
}];

// 入力が不正な場合、既存のNormalize出力と同じ形（input/search/extract/sources/warnings/
// generated_at）のオブジェクトを組み立てる。architected: 呼び出し元（バックエンド／n8n画面）は
// この形さえ見れば、Tavilyを呼び出した場合と同じ方法で結果を扱える。架空の情報では補わない。

const input = $('Input Ready').first().json;

return [{
  json: {
    input: {
      company_name: input.company_name,
      official_url: input.official_url,
      research_purpose: input.research_purpose,
    },
    search: null,
    extract: null,
    sources: [],
    warnings: ['入力エラー: ' + input._input_error],
    generated_at: new Date().toISOString(),
  },
}];
